begin;
select no_plan();
select ok(not has_function_privilege('anon','api.execute_owner_spill_cta_editor_server(uuid,text,jsonb)','EXECUTE'),'Anonymous gateway denied');
select ok(not has_function_privilege('authenticated','api.execute_owner_spill_cta_editor_server(uuid,text,jsonb)','EXECUTE'),'Browser cannot choose subject');
select ok(has_function_privilege('service_role','api.execute_owner_spill_cta_editor_server(uuid,text,jsonb)','EXECUTE'),'Fixed server gateway enabled');
set local role anon;
select throws_ok($$select api.execute_owner_spill_cta_editor_server(null,null,'{}')$$,'42501',null,'Actual anonymous gateway call denied');
reset role;
set local role authenticated;
select throws_ok($$select api.execute_owner_spill_cta_editor_server(null,null,'{}')$$,'42501',null,'Actual browser gateway call denied');
reset role;
select ok(not has_function_privilege('service_role','api.initialize_current_owner_blocks_from_spill_cta(jsonb)','EXECUTE'),'Original init remains closed');
select ok(not has_function_privilege('service_role','api.add_current_owner_spill_cta_block_working(jsonb)','EXECUTE'),'Original add remains closed');
select ok(not has_table_privilege('service_role','core.identity_block_spill_cta_working','SELECT,INSERT,UPDATE,DELETE'),'No raw marker table privilege');
insert into auth.users(id,email) values('27700000-0000-4000-8000-000000000001','cta-one@example.test'),('27700000-0000-4000-8000-000000000002','cta-two@example.test');
create temporary table actors as select auth_user_id,owner_id from core.owner_auth_bindings where auth_user_id in('27700000-0000-4000-8000-000000000001','27700000-0000-4000-8000-000000000002');
update core.owner_onboarding_progress set current_step='preview_publish',primary_use_case='personal' where owner_id in(select owner_id from actors);
insert into core.owner_handle_namespaces(normalized_handle,owner_id,namespace_kind) select 'cta277-'||right(auth_user_id::text,6),owner_id,'current' from actors;
update core.owners set onboarding_completed_at=now() where id in(select owner_id from actors);
insert into core.identity_working(owner_id,display_name,bio,revision) select owner_id,'Retained Profile','Retained Bio',2 from actors;
insert into core.identity_layout_working(owner_id,starter_key,revision) select owner_id,'clean',1 from actors;
insert into core.identity_publications(owner_id,snapshot,identity_revision,layout_revision,connection_revision,published_at) select owner_id,'{"legacy":true}',2,1,null,now() from actors;
create temporary table created(actor uuid,result jsonb);
grant select,insert on created to service_role;
create function pg_temp.allocate_cta(subject uuid,base bigint,visible boolean) returns jsonb language sql as $$ select api.execute_owner_spill_cta_editor_server(subject,case when base is null then 'initialize_current_owner_blocks_from_spill_cta' else 'add_current_owner_spill_cta_block_working' end,jsonb_build_object('input_intent',jsonb_build_object('action',case when base is null then 'initialize_spill_cta_block' else 'add_spill_cta_block' end,'base_collection_revision',base,'is_visible',visible,'spill_cta_working',jsonb_build_object('kind','spill_cta','target','owner_spill'))));$$;
grant execute on function pg_temp.allocate_cta(uuid,bigint,boolean) to service_role;
set local request.jwt.claims='{"role":"service_role","sub":"27700000-0000-4000-8000-000000000002"}';
set local request.jwt.claim.sub='27700000-0000-4000-8000-000000000002';
set local role service_role;
insert into created select '27700000-0000-4000-8000-000000000001',pg_temp.allocate_cta('27700000-0000-4000-8000-000000000001',null,false);
insert into created select '27700000-0000-4000-8000-000000000001',pg_temp.allocate_cta('27700000-0000-4000-8000-000000000001',1,true);
insert into created select '27700000-0000-4000-8000-000000000002',pg_temp.allocate_cta('27700000-0000-4000-8000-000000000002',null,false);
select is((select result->>'collection_revision' from created where actor='27700000-0000-4000-8000-000000000001' and result->>'collection_revision'='1'),'1','Explicit hidden first integration acknowledged');
select is((select result->>'collection_revision' from created where actor='27700000-0000-4000-8000-000000000001' and result->>'collection_revision'='2'),'2','Exact append acknowledged');
select is(pg_temp.allocate_cta('27700000-0000-4000-8000-000000000001',null,true)->>'status','already_initialized','Init replay cannot create another collection');
select is(pg_temp.allocate_cta('27700000-0000-4000-8000-000000000001',1,true)->>'status','stale_write','Old append cannot duplicate marker');
select is(pg_temp.allocate_cta('27700000-0000-4000-8000-000000000099',null,true)->>'status','owner_missing','Unknown subject cannot use ambient Owner');
select is(api.execute_owner_spill_cta_editor_server('27700000-0000-4000-8000-000000000001','publish_current_onboarding','{}')->>'status','unavailable','Publication not selectable');
select is(api.execute_owner_spill_cta_editor_server('27700000-0000-4000-8000-000000000001','add_current_owner_spill_cta_block_working','{"input_intent":{},"owner_id":"forged"}')->>'status','unavailable','Extra subject envelope denied');
select is(api.execute_owner_spill_cta_editor_server('27700000-0000-4000-8000-000000000001','add_current_owner_spill_cta_block_working','{"input_working":{}}')->>'status','unavailable','Wrong envelope denied');
select is(current_setting('request.jwt.claim.sub'),'27700000-0000-4000-8000-000000000002','Success and denials restore subject');
select is(current_setting('request.jwt.claims')::jsonb,'{"role":"service_role","sub":"27700000-0000-4000-8000-000000000002"}'::jsonb,'Complete claims restored');
reset role;
select is((select count(*)::int from core.identity_blocks_working where owner_id=(select owner_id from actors where auth_user_id='27700000-0000-4000-8000-000000000001')),2,'Own collection has exactly two members');
select is((select count(*)::int from core.identity_blocks_working where owner_id=(select owner_id from actors where auth_user_id='27700000-0000-4000-8000-000000000002')),1,'Foreign collection isolated');
select is((select count(*)::int from core.identity_block_spill_cta_working where owner_id in(select owner_id from actors)),3,'Atomic typed markers exist');
select is((select count(*)::int from core.identity_blocks_working where owner_id in(select owner_id from actors) and not is_visible),2,'Explicit hidden visibility retained');
create function pg_temp.fail_insert() returns trigger language plpgsql as $$begin raise exception 'fixture CTA insert failure';end;$$;
create trigger cta_editor_fixture before insert on core.identity_blocks_working for each row execute function pg_temp.fail_insert();
set local role service_role;
select throws_ok($$select pg_temp.allocate_cta('27700000-0000-4000-8000-000000000001',2,true)$$,'P0001','fixture CTA insert failure','Failed append is atomic');
select is(current_setting('request.jwt.claim.sub'),'27700000-0000-4000-8000-000000000002','Exception restores prior subject');
reset role;
drop trigger cta_editor_fixture on core.identity_blocks_working;
select is((select revision::text from core.identity_block_collections_working where owner_id=(select owner_id from actors where auth_user_id='27700000-0000-4000-8000-000000000001')),'2','Failed insert did not advance revision');
select is((select count(*)::int from core.identity_block_spill_cta_working where owner_id in(select owner_id from actors)),3,'Failed insert did not add marker');
update core.owners set account_state='restricted' where id=(select owner_id from actors where auth_user_id='27700000-0000-4000-8000-000000000001');
set local role service_role;
select is(pg_temp.allocate_cta('27700000-0000-4000-8000-000000000001',2,true)->>'status','owner_not_eligible','Current restriction denies append');
reset role;
select ok(not exists(select 1 from core.identity_publications where owner_id in(select owner_id from actors) and snapshot<>'{"legacy":true}'::jsonb),'Published snapshots unchanged');
select ok(not exists(select 1 from core.identity_working where owner_id in(select owner_id from actors) and (display_name<>'Retained Profile' or revision<>2)),'Source profile/revision unchanged');
select * from finish();
rollback;
